const AGENT_UNAVAILABLE_CODES: ReadonlySet<string> = new Set([
  'ENOENT',
  'EACCES',
  'EPERM',
]);

type LibraryImportJob = ReturnType<ProfileRecords['jobs']>[number];
type LibraryImportFailure = ReturnType<ProfileRecords['failures']>[number];

const firstImportFailure = (
  records: ProfileRecords,
  jobId: string,
): LibraryImportFailure | undefined => {
  const failures = records.failures(jobId);
  return (
    failures.find((item) => item.stage === 'download') ??
    failures.find((item) => item.stage === 'analysis')
  );
};

const isImportAnalyzed = (records: ProfileRecords, sourceId: string) => {
  const coverage = records.coverage(sourceId);
  return coverage.analyzed + coverage.unsupported >= coverage.references;
};

const importFailedStep = ({
  records,
  job,
  failure,
}: {
  records: ProfileRecords;
  job: LibraryImportJob;
  failure: LibraryImportFailure | undefined;
}): ProfileImportStep | null => {
  if (!job.isEnumerated) return 'enumerate';
  if (failure) return failure.stage;
  if (!isImportAnalyzed(records, job.sourceId)) return 'analysis';
  return isMemoryPlatformSupported() ? null : 'memory_start';
};

const failedImportReason = ({
  records,
  job,
  failure,
  failedStep,
}: {
  records: ProfileRecords;
  job: LibraryImportJob;
  failure: LibraryImportFailure | undefined;
  failedStep: ProfileImportStep | null;
}): DesignLibraryImportReason => {
  switch (failedStep) {
    case 'enumerate':
      return 'source_unavailable';
    case 'download':
      return 'images_unavailable';
    case 'analysis':
      if (!failure) return 'unknown';
      return AGENT_UNAVAILABLE_CODES.has(failure.reasonCode ?? '')
        ? 'agent_unavailable'
        : 'agent_failed';
    case 'memory_start':
      return 'search_unsupported';
    case 'index':
    case null:
      return isImportAnalyzed(records, job.sourceId)
        ? 'search_unavailable'
        : 'unknown';
    default: {
      const unhandled: never = failedStep;
      return unhandled;
    }
  }
};

const importDiagnosticDetail = (detail: string | null): string | null =>
  detail === null
    ? null
    : redactSensitiveText(detail.split(os.homedir()).join('~'));

const libraryImport = (
  records: ProfileRecords,
  job: LibraryImportJob,
  provider: DesignLibraryImport['provider'],
): DesignLibraryImport => {
  const coverage = records.coverage(job.sourceId);
  const progress = {
    jobId: job.id,
    provider,
    referenceCount: coverage.references,
    analyzedCount: coverage.analyzed,
  };
  if (job.state === 'pending')
    return {
      ...progress,
      state: 'pending',
      reason: job.error ? 'rate_limited' : null,
      diagnostics: null,
    };
  const failure = firstImportFailure(records, job.id);
  const failedStep = importFailedStep({ records, job, failure });
  return {
    ...progress,
    state: 'failed',
    reason: failedImportReason({ records, job, failure, failedStep }),
    diagnostics: {
      failedStep,
      reasonCode: failure?.reasonCode ?? null,
      detail: importDiagnosticDetail(failure?.error ?? job.error),
      platform: process.platform,
      arch: process.arch,
      nodeVersion: process.version,
    },
  };
};

const libraryImports = (records: ProfileRecords): DesignLibraryImport[] =>
  records.sources().flatMap(({ id, provider }) => {
    const job = lastReferenceJob(records, id);
    if (
      !isRemoteProfileProvider(provider) ||
      !job ||
      (job.state !== 'pending' && job.state !== 'failed')
    )
      return [];
    return [libraryImport(records, job, provider)];
  });

