export class DesignProfiles {
  private current?: ProfileContext;
  private opening: Promise<ProfileContext> | undefined;
  private isClosed = false;
  private readonly closing = new AbortController();
  readonly guidanceSync: GuidanceSync;
  readonly sourceSync = new SourceSyncSchedule({
    checks: () => this.sourceSyncChecks(),
    refresh: (input) => this.refreshSources(input),
  });
  constructor(private readonly options: DesignProfilesOptions) {
    this.guidanceSync = new GuidanceSync({
      accountId: options.accountId,
      withRecords: (operation, accountId) =>
        this.withProfileConnection(operation, accountId),
      serialize: (operation, accountId) =>
        this.serializeProfileWrite(operation, accountId),
      importImages: (records, input) =>
        this.importGuidanceImages(records, input),
      telemetry: options.telemetry,
      signal: this.closing.signal,
    });
  }

  async readDesignContext(input: {
    includeChecks?: boolean;
    includeDisabled?: boolean;
    importPlanId?: string;
    instructionIds?: string[];
    referenceSelection?: { profileId: string; keys: string[] };
  }) {
    return this.withReadOnlyRecords(async (records) => {
      if (!records) {
        if (input.importPlanId)
          throw new Error('Unknown reference import plan');
        if (input.instructionIds?.length || input.referenceSelection)
          throw new Error('The selected saved design context is unavailable');
        return {
          profileId: null,
          autonomy: 'off' as const,
          instructions: [],
          references: [],
        };
      }
      const selected = input.instructionIds
        ? [...new Set(input.instructionIds)].map((id) =>
            records.getGuidance(id),
          )
        : records
            .listGuidance()
            .filter((document) => input.includeDisabled || document.isEnabled);
      const instructions = selected.map((document) => {
        const { verifier } = records.getGuidanceVerifier(document.id);
        const sourceDigest = guidanceSourceDigest(document);
        return {
          ...document,
          sourceDigest,
          ...(input.includeChecks && verifier
            ? {
                verifier: {
                  markdown: verifier.markdown,
                  sourceDigest: verifier.sourceDigest,
                  isStale: sourceDigest !== verifier.sourceDigest,
                  ...(verifier.package
                    ? {
                        package: {
                          runtime: verifier.package.runtime,
                          entrypoint: verifier.package.entrypoint,
                          fileNames: verifier.package.files.map(
                            (file) => file.name,
                          ),
                        },
                      }
                    : {}),
                },
              }
            : {}),
        };
      });
      const selection = input.referenceSelection;
      const references = selection
        ? await this.readReferenceContexts(records, {
            ...selection,
            isDetailed: true,
          })
        : { references: [] };
      if (!references)
        throw new Error('The selected saved references are unavailable');
      const importPlan = input.importPlanId
        ? this.importPlanReceipt(records, input.importPlanId)
        : undefined;
      return {
        profileId: records.profile().id,
        autonomy: records.referenceAutonomy(),
        instructions,
        references: references.references,
        ...(importPlan ? { importPlan } : {}),
      };
    });
  }

  private importPlanReceipt(records: ProfileRecords, id: string) {
    const plan = records.plans.plan(id);
    const jobs = new Map(records.jobs().map((job) => [job.id, job]));
    return {
      ...referencePlanSummary(plan),
      coverageBasis: 'retained_job_references' as const,
      jobs: plan.jobIds.map((jobId) => {
        const job = jobs.get(jobId);
        if (!job)
          throw new Error(`Reference import job ${jobId} is unavailable`);
        return {
          ...job,
          coverage: records.importCoverage(jobId),
          failures: records.failures(jobId),
        };
      }),
    };
  }

  async saveReference(input: SavedReferenceInput) {
    return this.withReferenceRecords(async (records, accountId) => {
      const media = new ProfileMedia(records.directory);
      const remoteId = randomUUID();
      const referenceInput = await this.suppliedReferenceInput(
        input,
        media,
        remoteId,
      );
      const description =
        input.source.kind === 'text'
          ? ProfileObservationSchema.shape.description.parse(
              referenceInput[0].text.slice(0, MAX_OBSERVATION_CHARACTERS),
            )
          : undefined;
      this.guidanceAccount(accountId);
      const result = records.saveLocalReferences({
        source: {
          provider: referenceInput[0].provider,
          remoteId,
          title: input.title,
        },
        references: referenceInput,
      });
      if (description !== undefined)
        for (const reference of result.references)
          records.saveObservation({
            referenceId: reference.id,
            revision: reference.revision,
            description,
            runtime: 'user',
            evidence: 'observation',
          });
      records.queueIndex(records.rebuild()?.runtime ?? SAVED_REFERENCE_RUNTIME);
      return {
        profileId: records.profile().id,
        ...result,
        analysis: 'not_requested' as const,
        index: 'queued' as const,
      };
    });
  }

  private async suppliedReferenceInput(
    input: SavedReferenceInput,
    media: ProfileMedia,
    remoteId: string,
  ): Promise<ProfileReferenceInput[]> {
    const { source, title } = input;
    switch (source.kind) {
      case 'text': {
        const text = source.text.trim();
        if (!text) throw new Error('A saved text reference must contain text');
        return [{ provider: 'text', remoteId, title, text, media: [] }];
      }
      case 'images': {
        if (
          !source.files.length ||
          source.files.length > SAVED_REFERENCE_IMAGE_LIMIT
        )
          throw new Error(
            `Supply between 1 and ${SAVED_REFERENCE_IMAGE_LIMIT} image files`,
          );
        const images = [];
        let bytes = 0;
        for (const file of source.files) {
          const stat = await fs.lstat(file);
          if (
            !path.isAbsolute(file) ||
            !stat.isFile() ||
            stat.size > PROFILE_IMAGE_BYTES
          )
            throw new Error(
              'Supply bounded regular image files with absolute paths',
            );
          bytes += stat.size;
          if (bytes > PROFILE_UPLOAD_BYTES)
            throw new Error(
              'Supplied images exceed the reference upload budget',
            );
          images.push(await media.put(await fs.readFile(file)));
        }
        return images.map((image, index) => ({
          provider: 'image',
          remoteId: image.hash,
          title: images.length === 1 ? title : `${title} ${index + 1}`,
          text: '',
          media: [image],
        }));
      }
      case 'saved_direction': {
        if (!source.imageFile)
          throw new Error(
            'Saving a direction requires an existing screenshot file',
          );
        const variantInput: ProfileVariantInput = {
          projectId: source.projectId,
          sessionId: source.sessionId,
          variantId: source.variantId,
          imageFile: source.imageFile,
          note: source.note,
          runtime: 'codex',
        };
        const load = async () => {
          const signal = new AbortController().signal;
          if (this.options.variants)
            return this.options.variants.load(variantInput, signal);
          const library = await ProjectLibrary.open(this.options.root);
          const variants = new ProfileVariants({ library });
          try {
            return await variants.load(variantInput, signal);
          } finally {
            await variants.close();
            library.close();
          }
        };
        const saved = await load();
        const image = await media.put(saved.image);
        return [
          {
            ...saved.reference,
            title,
            media: [{ ...image, representation: 'variant' }],
          },
        ];
      }
    }
  }

  async removeReference(input: { profileId: string; referenceId: string }) {
    return this.withReferenceRecords((records) => {
      if (records.profile().id !== input.profileId)
        throw new Error('The selected reference belongs to another profile');
      records.removeReference(input.referenceId);
      return {
        profileId: input.profileId,
        referenceId: input.referenceId,
        isRemoved: true,
      };
    });
  }

  private async withReadOnlyRecords<T>(
    operation: (records: ProfileRecords | null) => Promise<T> | T,
  ): Promise<T> {
    const accountId = this.guidanceAccount();
    const records = ProfileRecords.openReadOnly({
      root: this.options.root,
      accountId,
    });
    try {
      this.guidanceAccount(accountId);
      const result = await operation(records);
      this.guidanceAccount(accountId);
      return result;
    } finally {
      records?.close();
    }
  }

  async listGuidance(expectedAccountId?: string) {
    return this.withGuidanceRecords(
      (records) => records.listGuidance(),
      expectedAccountId,
    );
  }

  async getGuidance(id: string, expectedAccountId?: string) {
    return this.withGuidanceRecords(
      (records) => records.getGuidance(id),
      expectedAccountId,
    );
  }

  async addGuidance(input: GuidanceUpload, expectedAccountId?: string) {
    const accountId = this.guidanceAccount(expectedAccountId);
    const { images, ...content } = GuidanceUploadSchema.parse(input);
    return this.withGuidanceRecords(async (records) => {
      const attachments = await this.importGuidanceImages(records, {
        ...content,
        images,
      });
      this.guidanceAccount(accountId);
      const document = records.addGuidance({
        ...content,
        ...(attachments.length ? { attachments } : {}),
      });
      const warning = guidanceWarning(
        records.resolveGuidance({ mode: 'auto', excludedIds: [] }),
      );
      return { ...document, ...(warning ? { guidanceWarning: warning } : {}) };
    }, expectedAccountId);
  }

  async updateGuidance(
    input: GuidanceUploadUpdate & { id: string },
    expectedAccountId?: string,
  ) {
    const accountId = this.guidanceAccount(expectedAccountId);
    const { id, ...body } = input;
    const { images, ...content } = GuidanceUploadUpdateSchema.parse(body);
    return this.withGuidanceRecords(async (records) => {
      const current = records.getGuidance(id);
      if (current.origin && content.markdown !== undefined)
        throw new GuidanceError(
          'guidance_source_changed',
          'Disconnect the source before editing this document manually.',
        );
      const attachments =
        content.markdown === undefined
          ? undefined
          : await this.importGuidanceImages(records, {
              markdown: content.markdown,
              images,
            });
      this.guidanceAccount(accountId);
      const document = records.updateGuidance({
        id,
        ...content,
        ...(attachments !== undefined ? { attachments } : {}),
      });
      const warning = guidanceWarning(
        records.resolveGuidance({ mode: 'auto', excludedIds: [] }),
      );
      return { ...document, ...(warning ? { guidanceWarning: warning } : {}) };
    }, expectedAccountId);
  }

  async removeGuidance(id: string, expectedAccountId?: string) {
    return this.withGuidanceRecords(
      (records) => records.removeGuidance(id),
      expectedAccountId,
    );
  }

  private async importGuidanceImages(
    records: ProfileRecords,
    input: Pick<GuidanceUpload, 'markdown' | 'images'>,
  ) {
    const { references, uploads } = validateGuidanceImages(input);
    const media = new ProfileMedia(records.directory);
    const stored = new Map<
      string,
      Awaited<ReturnType<ProfileMedia['put']>> & { path: string }
    >();
    for (const { bytes, media: descriptor } of uploads.values()) {
      if (stored.has(descriptor.hash)) continue;
      const image = await media.put(bytes);
      stored.set(image.hash, { ...image, path: await media.resolve(image) });
    }
    return references.map((reference) => {
      const upload = uploads.get(reference.source);
      const image = upload && stored.get(upload.media.hash);
      if (!image)
        throw guidanceAssetError(
          reference.source,
          'Required image was not stored.',
        );
      return { ...reference, ...image };
    });
  }

  async resolveGuidance(input: GuidanceSelection, expectedAccountId?: string) {
    const selection = GuidanceSelectionSchema.parse(input);
    const accountId = this.guidanceAccount(expectedAccountId);
    if (selection.mode === 'off') return { accountId, guidance: [] };
    return this.withGuidanceRecords(async (records) => {
      const guidance = await this.materializeGuidance(
        records,
        records.resolveGuidance(selection),
      );
      const warning = guidanceWarning(guidance);
      return {
        accountId,
        guidance,
        ...(warning ? { guidanceWarning: warning } : {}),
      };
    }, accountId);
  }

  async prepareGuidanceVerification(
    id: string,
    expectedAccountId?: string,
  ): Promise<GuidanceVerification> {
    return this.withGuidanceRecords(async (records) => {
      const { source, sourceDigest, verifier } =
        records.getGuidanceVerifier(id);
      const [resolvedSource] = await this.materializeGuidance(records, [
        source,
      ]);
      const resolved = {
        source: resolvedSource,
        sourceDigest,
        execution: 'host_required' as const,
      };
      if (!verifier)
        return {
          ...resolved,
          verifierState: 'missing',
          nextAction: {
            action: 'create_context_verifier',
            instructions: `Author and execute a focused verifier against this source and the user-selected target. ${VERIFICATION_TARGET_INSTRUCTIONS} Record observable checks and evidence before offering to save it for reuse.`,
          },
        };
      if (verifier.sourceDigest !== sourceDigest)
        return {
          ...resolved,
          verifier,
          verifierState: 'stale',
          nextAction: {
            action: 'revise_context_verifier',
            instructions: `The source changed after this verifier was saved. ${VERIFICATION_TARGET_INSTRUCTIONS} Revise and execute a temporary recipe against the supplied source before offering to replace the saved verifier.`,
          },
        };
      if (!verifier.package) {
        return {
          ...resolved,
          verifier,
          verifierState: 'ready',
          nextAction: {
            action: 'execute_context_recipe',
            instructions: `This saved verifier is a Markdown recipe without an executable package, so \`rivet context verify\` cannot run it. Follow the recipe once with the host's own tools against this source and the user-selected target. ${VERIFICATION_TARGET_INSTRUCTIONS} Report pass, fail, or unable to verify with evidence. Retrieval has not executed any checks.`,
          },
        };
      }
      return {
        ...resolved,
        verifier,
        verifierState: 'ready',
        packageDirectory: await materializeTextFiles({
          files: verifier.package.files,
          directory: path.join(records.directory, 'guidance-verifiers'),
        }),
        nextAction: {
          action: 'run_context_verifier',
          instructions: `Execute the saved verifier against this source and the user-selected target. ${VERIFICATION_TARGET_INSTRUCTIONS} Report pass, fail, or unable to verify with evidence. Retrieval has not executed any checks.`,
        },
      };
    }, expectedAccountId);
  }

  private async materializeGuidance(
    records: ProfileRecords,
    documents: GuidanceDocument[],
  ): Promise<GuidanceDocument[]> {
    const guidance = await materializeGuidanceReferences({
      documents,
      dataDirectory: records.directory,
    });
    const media = new ProfileMedia(records.directory);
    const paths = new Map<string, string>();
    for (const document of guidance) {
      for (const image of document.attachments ?? []) {
        try {
          image.path = paths.get(image.hash) ?? (await media.resolve(image));
          paths.set(image.hash, image.path);
        } catch {
          throw guidanceAssetError(
            image.source,
            `Required image for "${document.title}" is missing or unreadable. Update the document to restore it.`,
          );
        }
      }
    }
    return guidance;
  }

  private guidanceAccount(expectedAccountId?: string): string {
    const accountId = this.options.accountId();
    if (expectedAccountId && expectedAccountId !== accountId)
      throw new GuidanceError(
        'guidance_account_changed',
        'Saved guidance account changed. Sign in and retry.',
      );
    if (!accountId)
      throw new GuidanceError(
        'guidance_auth_required',
        'Sign in to Rivet to use saved guidance',
      );
    return accountId;
  }

  private async withGuidanceRecords<T>(
    operation: (records: ProfileRecords) => Promise<T> | T,
    expectedAccountId?: string,
  ): Promise<T> {
    const accountId = this.guidanceAccount(expectedAccountId);
    try {
      const result = await this.withReferenceRecords(
        (records, openedAccountId) => {
          if (openedAccountId !== accountId)
            throw new GuidanceError(
              'guidance_account_changed',
              'Saved guidance account changed. Sign in and retry.',
            );
          return operation(records);
        },
      );
      this.guidanceAccount(accountId);
      return result;
    } catch (error) {
      this.guidanceAccount(accountId);
      throw error;
    }
  }

  async sourceSyncStates(
    family?: SourceFamily,
    expectedAccountId?: string,
  ): Promise<SourceSyncState[]> {
    const accountId = this.guidanceAccount(expectedAccountId);
    const now = Date.now();
    const read = (records: ProfileRecords) => [
      ...(family === 'references'
        ? []
        : contextSyncStates(records.listGuidance(), now)),
      ...(family === 'context' ? [] : referenceSyncStates(records, now)),
    ];
    return this.current?.accountId === accountId
      ? read(this.current.records)
      : this.withGuidanceRecords(read, accountId);
  }

  async requestSourceRefresh(
    input: SourceRefreshRequest,
    expectedAccountId?: string,
  ): Promise<SourceRefreshResult[]> {
    const request = SourceRefreshRequestSchema.parse(input);
    const accountId = this.guidanceAccount(expectedAccountId);
    const context = await this.guidanceContext(accountId);
    const families =
      'all' in request
        ? request.family
          ? [request.family]
          : SOURCE_FAMILIES
        : [request.family];
    const results: SourceRefreshResult[] = [];
    if (families.includes('context'))
      results.push(...this.refreshContextNow(context, request));
    if (families.includes('references'))
      results.push(...this.refreshReferencesNow(context, request));
    return results;
  }

  private refreshContextNow(
    context: ProfileContext,
    request: SourceRefreshRequest,
  ): SourceRefreshResult[] {
    const documents =
      'all' in request
        ? context.records
            .listGuidance()
            .filter((document) => document.origin && document.sync)
        : [context.records.getGuidance(request.sourceId)];
    const results = documents.map((document): SourceRefreshResult => {
      if (!document.origin || !document.syncMode)
        throw new GuidanceError(
          'guidance_not_found',
          'This document has no connected source to refresh',
        );
      if ('sourceId' in request) assertExplicitSourceSync(document.syncMode);
      return {
        family: 'context',
        sourceId: document.id,
        status: isSourceSyncAllowed({
          syncMode: document.syncMode,
          trigger: 'explicit',
        })
          ? 'queued'
          : 'skipped_off',
      };
    });
    const ids = results
      .filter((result) => result.status === 'queued')
      .map((result) => result.sourceId);
    if (ids.length)
      void this.guidanceSync
        .refresh({
          accountId: context.accountId,
          ids,
          trigger: 'explicit',
          signal: this.closing.signal,
        })
        .catch(() => undefined);
    return results;
  }

  private refreshReferencesNow(
    context: ProfileContext,
    request: SourceRefreshRequest,
  ): SourceRefreshResult[] {
    const refreshable = context.records
      .sources()
      .filter(
        (source) =>
          isRemoteProfileProvider(source.provider) &&
          lastReferenceJob(context.records, source.id) !== undefined,
      );
    const requested =
      'sourceId' in request
        ? refreshable.filter((source) => source.id === request.sourceId)
        : refreshable;
    if ('sourceId' in request && !requested.length)
      throw new SourceNotFoundError();
    return requested.map((source): SourceRefreshResult => {
      const result = { family: 'references' as const, sourceId: source.id };
      const jobs = context.records
        .jobs()
        .filter((job) => job.sourceId === source.id);
      const last = jobs[jobs.length - 1];
      if ('sourceId' in request) assertExplicitSourceSync(source.syncMode);
      if (
        !isSourceSyncAllowed({ syncMode: source.syncMode, trigger: 'explicit' })
      )
        return { ...result, status: 'skipped_off' };
      if (!context.records.profile().isEnabled)
        return { ...result, status: 'profile_disabled' };
      if (jobs.some((job) => ['pending', 'paused'].includes(job.state)))
        return { ...result, status: 'skipped_in_progress' };
      const job = context.records.startImport({
        sourceId: source.id,
        runtime: last.runtime,
      });
      this.enqueueImport(context, job.id, 'refresh');
      return { ...result, status: 'queued', jobId: job.id };
    });
  }

  private async sourceSyncChecks(): Promise<SourceSyncChecks | null> {
    const accountId = this.options.accountId();
    if (!accountId) return null;
    const checks = (records: ProfileRecords) => [
      ...guidanceSyncChecks(records.listGuidance()),
      ...referenceSyncChecks(records),
    ];
    return {
      accountId,
      checks:
        this.current?.accountId === accountId
          ? checks(this.current.records)
          : await this.withGuidanceRecords(checks, accountId),
    };
  }

  private async refreshSources({
    accountId,
    checks,
    signal,
  }: SourceSyncChecks & { signal: AbortSignal }): Promise<void> {
    const ids = (family: SourceFamily) =>
      checks
        .filter((check) => check.family === family)
        .map((check) => check.sourceId);
    const contextIds = ids('context');
    if (contextIds.length)
      await this.guidanceSync.refresh({
        accountId,
        ids: contextIds,
        trigger: 'automatic',
        signal,
      });
    const referenceIds = ids('references');
    if (!referenceIds.length) return;
    signal.throwIfAborted();
    const context = await this.guidanceContext(accountId);
    signal.throwIfAborted();
    for (const id of referenceIds) this.autoRefreshReference(context, id);
  }

  private autoRefreshReference(context: ProfileContext, sourceId: string) {
    const last = lastReferenceJob(context.records, sourceId);
    if (!last || !isAutomaticReferenceSyncAllowed(context.records, sourceId))
      return;
    const job = context.records.startImport({
      sourceId,
      runtime: last.runtime,
    });
    this.enqueueImport(context, job.id, 'auto_refresh');
  }

  private async guidanceContext(accountId: string): Promise<ProfileContext> {
    const context = await this.context({ shouldResume: false });
    if (context.accountId !== this.guidanceAccount(accountId))
      throw new GuidanceError(
        'guidance_account_changed',
        'Saved guidance account changed. Sign in and retry.',
      );
    return context;
  }

  private async withProfileConnection<T>(
    operation: (records: ProfileRecords) => Promise<T> | T,
    expectedAccountId?: string,
  ): Promise<T> {
    const accountId = this.guidanceAccount(expectedAccountId);
    const context = await this.guidanceContext(accountId);
    const write = Promise.resolve().then(() => operation(context.records));
    context.directWrites.add(write);
    try {
      const result = await write;
      this.guidanceAccount(accountId);
      return result;
    } finally {
      context.directWrites.delete(write);
    }
  }

  private async serializeProfileWrite<T>(
    operation: (records: ProfileRecords) => Promise<T> | T,
    expectedAccountId: string,
  ): Promise<T> {
    const accountId = this.guidanceAccount(expectedAccountId);
    const context = await this.guidanceContext(accountId);
    const result = context.work.then(async () => {
      context.abort.signal.throwIfAborted();
      this.guidanceAccount(accountId);
      const value = await operation(context.records);
      this.guidanceAccount(accountId);
      return value;
    });
    context.work = result.then(
      () => undefined,
      () => undefined,
    );
    return result;
  }

  async discoverReferences({
    isAuthorizationAllowed = true,
    signal = new AbortController().signal,
    ...input
  }: ReferenceDiscoveryRequest & {
    signal?: AbortSignal;
    isAuthorizationAllowed?: boolean;
  }) {
    try {
      const discovery = await this.withReferenceRecords((records, accountId) =>
        this.planning(records, accountId).discover({ ...input, signal }),
      );
      const provider = referenceProvider(discovery.profile);
      return {
        ...discovery,
        provider,
        scopeDisclosure: referenceScopeDisclosure[provider],
      };
    } catch (error) {
      if (
        !(error instanceof ReferenceConnectionError) ||
        error.reason !== 'not_connected' ||
        !('provider' in input) ||
        !isAuthorizationAllowed
      )
        throw error;
      const connection = await (
        this.options.integrations ?? new IntegrationsClient()
      ).connect(input.provider);
      if (connection.status !== 'ok') throw new Error(connection.message);
      return {
        status: 'authorization_required' as const,
        provider: input.provider,
        authUrl: connection.authUrl,
        message:
          'Connect this account, then repeat discovery. Signing in does not approve an import.',
      };
    }
  }

  async planReferences(
    input: ReferencePlanRequest,
    signal = new AbortController().signal,
  ) {
    return this.withReferenceRecords(async (records, accountId) =>
      referencePlanSummary(
        await this.planning(records, accountId).prepare(input, signal),
      ),
    );
  }

  async referencePlan(id: string) {
    return this.withReferenceRecords((records) =>
      referencePlanSummary(records.plans.plan(id)),
    );
  }

  async referenceOnboarding(
    action?: ReferenceOnboardingAction,
    provider?: ReferenceProvider,
  ) {
    return this.withReferenceRecords((records) => ({
      providers: (provider ? [provider] : ReferenceProviderSchema.options).map(
        (selected) =>
          action
            ? records.plans.updateOnboarding(action, selected)
            : records.plans.onboarding(selected),
      ),
    }));
  }

  async referenceNotice() {
    return this.withReferenceRecords((records) => {
      const providers = ReferenceProviderSchema.options.flatMap((provider) => {
        const notice = records.plans.notice(provider);
        return notice ? [notice] : [];
      });
      return providers.length
        ? {
            providers,
            message:
              'Offer to connect design references from these services. Ask which services the user wants, discover their collections, then show the scope and agent usage disclosure before requesting import approval. The user can choose later or dismiss for one provider or all providers.',
          }
        : null;
    });
  }

  async importReferences(input: {
    id: string;
    revision: string;
    isApproved: boolean;
  }) {
    const request = ReferenceApprovalSchema.parse(input);
    const accountId = this.options.accountId();
    if (!accountId)
      throw new Error('Sign in to Rivet to connect design references');
    const context = await this.context();
    const wasEnabled = context.records.profile().isEnabled;
    const plan = await this.withReferenceRecords(
      async (records, currentAccountId) => {
        const pending = records.plans.plan(request.id);
        if (!pending.approvedAt)
          await this.planning(records, currentAccountId).verifyAccount(
            pending.profile,
            AbortSignal.timeout(APPROVAL_TIMEOUT_MS),
          );
        return records.approvePlan(request);
      },
    );
    if (
      context.accountId !== accountId ||
      accountId !== this.options.accountId()
    )
      throw new Error('Profile account changed during import approval');
    if (context.records.profile().isEnabled) {
      if (!wasEnabled) this.resume(context, plan.jobIds);
      for (const id of plan.jobIds) this.enqueueImport(context, id, 'connect');
    }
    return referencePlanSummary(plan);
  }

  private planning(records: ProfileRecords, accountId: string) {
    return new ProfilePlanning({
      records,
      integrations:
        this.options.referenceIntegrations ?? new IntegrationsClient(),
      connectors: this.options.referenceConnectors ?? new IntegrationsClient(),
      isCurrentAccount: () => this.options.accountId() === accountId,
    });
  }

  private async withReferenceRecords<T>(
    operation: (records: ProfileRecords, accountId: string) => Promise<T> | T,
  ): Promise<T> {
    const accountId = this.options.accountId();
    if (!accountId)
      throw new Error('Sign in to Rivet to connect design references');
    const records = await ProfileRecords.open({
      root: this.options.root,
      accountId,
    });
    try {
      if (accountId !== this.options.accountId())
        throw new Error('Profile account changed during reference planning');
      const result = await operation(records, accountId);
      if (accountId !== this.options.accountId())
        throw new Error('Profile account changed during reference planning');
      return result;
    } finally {
      records.close();
    }
  }

  private plannedRefresh(records: ProfileRecords, sourceId: string) {
    const source = records.plans.sourcePlan(sourceId);
    if (!source) return null;
    const discovery = records.plans.discovery(source.discoveryId);
    return {
      status: 'approval_required' as const,
      provider: referenceProvider(discovery.profile),
      profileUrl: discovery.profile.url,
      collectionId: source.collectionId,
      message:
        'Discover this reference provider again, prepare a plan for the selected collection, and ask the user to approve its scope and agent usage before import.',
    };
  }

  async status() {
    const context = await this.context();
    return this.profileStatus(context);
  }

  private profileStatus(context: ProfileContext) {
    return {
      profile: context.records.profile(),
      sources: context.records.sources(),
      jobs: context.records.jobs(),
      rebuild: context.records.rebuild(),
      engine: context.memory.isReady ? 'ready' : 'unavailable',
      issue: context.issue,
      counts: context.records.coverage(),
      referenceOnboarding: ReferenceProviderSchema.options.map((provider) =>
        context.records.plans.onboarding(provider),
      ),
    };
  }

  async diagnostics() {
    const context = await this.context();
    const assets = new Map(
      context.records
        .references()
        .flatMap((reference) =>
          reference.media.map((media) => [media.hash, media] as const),
        ),
    );
    const invalid: string[] = [];
    for (const media of assets.values()) {
      context.abort.signal.throwIfAborted();
      try {
        await context.media.resolve(media);
      } catch {
        invalid.push(media.hash);
      }
    }
    if (context.accountId !== this.options.accountId())
      throw new Error('Profile account changed during diagnostics');
    return {
      ...this.profileStatus(context),
      schemaVersion: PROFILE_SCHEMA_VERSION,
      failures: context.records.failures(),
      components: {
        engineVersion: ENGINE_VERSION,
        embeddingRevision: EMBEDDING_REVISION,
      },
      sources: context.records.sources().map((source) => ({
        ...source,
        coverage: context.records.coverage(source.id),
      })),
      media: { checked: assets.size, invalid },
    };
  }

  async reindex(runtime: ProfileRuntime) {
    const context = await this.context();
    if (!context.records.profile().isEnabled)
      throw new Error('Enable the design profile before rebuilding its index');
    const queued = context.records.reindex(runtime);
    this.enqueue(context, () => this.runRebuild(context));
    return { queued };
  }

  private async runRebuild(context: ProfileContext): Promise<void> {
    const job = context.records.rebuild();
    if (!job) return;
    const started = Date.now();
    try {
      await context.memory.start();
      await this.flush(context, job.runtime);
      context.records.completeRebuild(job.id);
      context.issue = null;
      const sources = context.records.sources();
      this.options.telemetry?.trackProfileOperation({
        stage: 'maintenance',
        operation: 'index_rebuild',
        outcome: 'completed',
        durationMs: Date.now() - started,
        referenceCount: context.records.coverage().indexed,
        providerCount: new Set(sources.map((source) => source.provider)).size,
        sourceCount: sources.length,
      });
    } catch (error) {
      this.options.telemetry?.trackProfileOperation({
        stage: 'maintenance',
        operation: 'index_rebuild',
        outcome: 'failed',
        durationMs: Date.now() - started,
        error,
      });
      throw error;
    }
  }

  async updateSettings(input: ProfileSettings) {
    const context = await this.context({ shouldResume: false });
    context.records.updateSettings(input);
    if (input.isEnabled) this.resume(context);
    if (input.isEnabled === false) {
      context.schedule.stop();
      context.abort.abort();
      await context.memory.close();
      await context.work;
      context.abort = new AbortController();
    }
    return this.profileStatus(context);
  }

  async disable(): Promise<void> {
    await this.updateSettings({ isEnabled: false });
  }

  async addText({
    title,
    text,
    runtime,
    evidence,
  }: {
    title: string;
    text: string;
    runtime: ProfileRuntime;
    evidence: 'observation' | 'preference';
  }) {
    const context = await this.context();
    if (!context.records.profile().isEnabled)
      throw new Error('Enable the design profile before importing references');
    context.records.queueIndex(runtime);
    const source = context.records.addSource({
      provider: 'text',
      remoteId: randomUUID(),
      title,
    });
    const reference = context.records.saveReference({
      sourceId: source.id,
      reference: {
        provider: 'text',
        remoteId: source.id,
        title,
        text,
        media: [],
      },
    });
    context.records.saveObservation({
      referenceId: reference.id,
      revision: reference.revision,
      description: text,
      runtime: 'user',
      evidence,
    });
    this.enqueue(context, () => this.runRebuild(context));
    return { source, reference };
  }

  async addImages({
    title,
    files,
    runtime,
  }: {
    title: string;
    files: string[];
    runtime: ProfileRuntime;
  }) {
    const context = await this.context();
    if (!context.records.profile().isEnabled)
      throw new Error('Enable the design profile before importing references');
    const images = [];
    for (const file of files) {
      const stat = await fs.lstat(file);
      if (!stat.isFile() || stat.size > PROFILE_IMAGE_BYTES)
        throw new Error('Profile imports require bounded regular image files');
      images.push(await context.media.put(await fs.readFile(file)));
    }
    const source = context.records.addSource({
      provider: 'image',
      remoteId: randomUUID(),
      title,
    });
    const job = context.records.startImport({ sourceId: source.id, runtime });
    const references: ProfileReferenceInput[] = images.map((media, index) => ({
      provider: 'image',
      remoteId: media.hash,
      title: `${title} ${index + 1}`,
      text: '',
      media: [media],
    }));
    context.records.saveImportPage({
      jobId: job.id,
      references,
      cursor: null,
      isComplete: true,
      total: new Set(references.map((reference) => reference.remoteId)).size,
    });
    this.enqueueImport(context, job.id, 'upload');
    return { source, jobId: job.id };
  }

  async pins(projectId?: string) {
    await this.context();
    if (!this.options.variants)
      throw new Error('Saved directions are unavailable in this coordinator');
    return this.options.variants.pins(projectId);
  }

  async addVariant(input: ProfileVariantInput) {
    const value = ProfileVariantInputSchema.parse(input);
    const context = await this.context();
    const signal = context.abort.signal;
    if (!context.records.profile().isEnabled)
      throw new Error('Enable the design profile before saving directions');
    if (!this.options.variants)
      throw new Error('Saved directions are unavailable in this coordinator');
    const saved = await this.options.variants.load(value, signal);
    const media = await context.media.put(saved.image);
    signal.throwIfAborted();
    if (context.accountId !== this.options.accountId())
      throw new Error('Profile account changed while saving the direction');
    const result = context.records.saveLocalImport({
      source: {
        provider: 'variant',
        remoteId: saved.reference.remoteId,
        title: saved.reference.title,
      },
      reference: {
        ...saved.reference,
        media: [{ ...media, representation: 'variant' }],
      },
      runtime: value.runtime,
    });
    this.enqueueImport(context, result.job.id, 'upload');
    return { source: result.source, jobId: result.job.id };
  }

  async connect(input: { url: string; runtime: ProfileRuntime }) {
    const cosmos = (() => {
      try {
        return parseCosmosUrl(input.url);
      } catch {
        return null;
      }
    })();
    if (cosmos) {
      const approval = await this.withReferenceRecords((records) => {
        const source = records.plans.sourceByUrl(cosmos.url);
        return source ? this.plannedRefresh(records, source.sourceId) : null;
      });
      if (approval) return approval;
    }
    const context = await this.context();
    if (!context.records.profile().isEnabled)
      throw new Error('Enable the design profile before importing references');
    let xAccount: XAccount | undefined;
    if (isXBookmarkUrl(input.url)) {
      const client = this.options.integrations ?? new IntegrationsClient();
      const listed = await client.listIntegrations();
      if (
        context.accountId !== this.options.accountId() ||
        !context.records.profile().isEnabled
      )
        throw new Error(
          'Profile account changed or was disabled during X authorization',
        );
      if (listed.status !== 'ok') throw new Error(listed.message);
      const connected = listed.integrations.find(
        (integration) =>
          integration.provider === 'x' && integration.status === 'connected',
      );
      if (!connected) {
        const authorization = await client.connect('x');
        if (
          context.accountId !== this.options.accountId() ||
          !context.records.profile().isEnabled
        )
          throw new Error(
            'Profile account changed or was disabled during X authorization',
          );
        if (authorization.status !== 'ok')
          throw new Error(authorization.message);
        return {
          status: 'authorization_required' as const,
          provider: 'x' as const,
          authUrl: authorization.authUrl,
        };
      }
      xAccount = XAccountSchema.parse({
        id: connected.externalAccountId,
        username: connected.externalUsername,
      });
      if (
        context.accountId !== this.options.accountId() ||
        !context.records.profile().isEnabled
      )
        throw new Error(
          'Profile account changed or was disabled during X authorization',
        );
    }
    const result = context.imports.connect({ ...input, xAccount });
    this.enqueueImport(context, result.job.id, 'connect');
    return result;
  }

  async updateJob({
    id,
    action,
  }: {
    id: string;
    action: 'pause' | 'resume' | 'retry';
  }) {
    const context = await this.context();
    const job = context.records.jobs().find((item) => item.id === id);
    if (!job) throw new Error('Unknown profile job');
    if (action !== 'pause' && !context.records.profile().isEnabled)
      throw new Error('Enable the design profile before resuming imports');
    if (action !== 'pause')
      assertExplicitSourceSync(context.records.source(job.sourceId).syncMode);
    context.records.updateJob({
      id,
      state: action === 'pause' ? 'paused' : 'pending',
    });
    if (action !== 'pause') this.enqueueImport(context, id, 'retry');
    return this.status();
  }

  async refresh({ id, runtime }: { id: string; runtime: ProfileRuntime }) {
    const context = await this.context();
    const source = context.records.source(id);
    assertExplicitSourceSync(source.syncMode);
    if (!context.records.profile().isEnabled)
      throw new Error('Enable the design profile before refreshing references');
    if (!isRemoteProfileProvider(source.provider))
      throw new Error('Only connected provider sources support refresh');
    const job = context.records.startImport({ sourceId: id, runtime });
    this.enqueueImport(context, job.id, 'refresh');
    return { job };
  }

  async updateSource({
    id,
    isIncluded,
    isRemoved,
    syncMode,
    runtime,
  }: {
    id: string;
    isIncluded?: boolean;
    isRemoved?: boolean;
    syncMode?: SourceSyncMode;
    runtime: ProfileRuntime;
  }): Promise<void> {
    const context = await this.context({ shouldResume: false });
    const resume = () => {
      if (!context.isResumed && context.records.profile().isEnabled)
        this.resume(context);
    };
    if (syncMode) {
      context.records.setSourceSyncMode({ id, syncMode });
      if (isIncluded === undefined && !isRemoved) {
        resume();
        return;
      }
    }
    context.records.queueIndex(runtime);
    if (isRemoved) context.records.removeSource(id);
    else if (isIncluded !== undefined)
      context.records.setSourceIncluded({ sourceId: id, isIncluded });
    resume();
    if (context.records.profile().isEnabled)
      this.enqueue(context, () => this.runRebuild(context));
  }

  async references(sourceId?: string) {
    const context = await this.context();
    return context.records.references(sourceId).map((reference) => ({
      ...reference,
      observation: context.records.observation(reference.id),
    }));
  }

  async library(): Promise<DesignLibrarySnapshot> {
    return this.withReferenceRecords((records) => ({
      profileId: records.profile().id,
      revision: records.profile().revision,
      isEnabled: records.profile().isEnabled,
      sources: librarySources(records),
      references: records.libraryReferences(),
      imports: libraryImports(records),
    }));
  }

  async search(
    input: DesignReferenceSearchRequest,
  ): Promise<DesignReferenceSearchResult> {
    const context = await this.context();
    const records = context.records;
    const matches = await this.searchLibraryWithSavedText(context, input);
    if (context.accountId !== this.options.accountId())
      throw new Error('Profile account changed during reference search');
    return profileSearchResult({
      profileId: records.profile().id,
      query: input.query,
      matches,
      allReferences: records.libraryReferences(),
      sources: librarySources(records),
      coverage: records.coverage(),
      limit: input.limit,
    });
  }

  private async searchLibraryWithSavedText(
    context: ProfileContext,
    input: DesignReferenceSearchRequest,
  ): Promise<DesignLibraryMatch[]> {
    const savedText = () =>
      context.index.searchSavedText({
        query: input.query,
        sourceFilterId: input.sourceId,
      });
    const { indexed, pendingIndex } = context.records.coverage();
    if (!isMemoryPlatformSupported() || (!indexed && !pendingIndex))
      return savedText();
    try {
      await context.memory.start();
      await context.index.flush(input.runtime, context.abort.signal);
      return await context.index.searchLibrary({
        runtime: input.runtime,
        query: input.query,
        sourceFilterId: input.sourceId,
        signal: context.abort.signal,
      });
    } catch (error) {
      log.warn('Semantic reference search unavailable; using saved text', {
        error: errorMessage(error, 'Semantic reference search failed'),
      });
      return savedText();
    }
  }

  async searchForAgent(
    input: DesignReferenceSearchRequest,
    expectedAccountId = this.options.accountId(),
  ): Promise<AgentReferenceSearchResult> {
    const started = Date.now();
    const engine = { isStarted: false };
    try {
      const result = await this.runAgentSearch(
        input,
        expectedAccountId,
        engine,
      );
      const budgeted = budgetAgentSearchResult(result);
      const durationMs = Date.now() - started;
      this.options.telemetry?.trackProfileOperation({
        stage: 'action',
        operation: 'reference_search',
        outcome: 'completed',
        durationMs,
        latencyMs: durationMs,
        searchStatus: result.status,
        searchMode: result.searchMode,
        isEngineStarted: engine.isStarted,
        autonomySetting: result.autonomy,
        resultCount: budgeted.results.length,
        semanticResultCount: budgeted.results.filter(
          (hit) => hit.matchedBy === 'semantic',
        ).length,
        savedTextResultCount: budgeted.results.filter(
          (hit) => hit.matchedBy === 'saved_text',
        ).length,
        unanalyzedResultCount: budgeted.results.filter(
          (hit) => !hit.hasAnalysis,
        ).length,
        resultBytes: Buffer.byteLength(JSON.stringify(budgeted)),
      });
      return result;
    } catch (error) {
      this.options.telemetry?.trackProfileOperation({
        stage: 'action',
        operation: 'reference_search',
        outcome: 'failed',
        durationMs: Date.now() - started,
        isEngineStarted: engine.isStarted,
        error,
      });
      throw error;
    }
  }

  private async runAgentSearch(
    input: DesignReferenceSearchRequest,
    expectedAccountId: string | undefined,
    engine: { isStarted: boolean },
  ): Promise<AgentReferenceSearchResult> {
    const context = await this.context({ shouldResume: false });
    if (context.accountId !== expectedAccountId)
      throw new ProfileContextConflict(
        'The Rivet coordinator is signed in to a different account than this search',
      );
    const { records } = context;
    const respond = (
      status: AgentSearchStatus,
      matches: DesignLibraryMatch[] = context.index.searchSavedText({
        query: input.query,
        sourceFilterId: input.sourceId,
      }),
    ): AgentReferenceSearchResult => {
      if (context.accountId !== this.options.accountId())
        throw new Error('Profile account changed during reference search');
      const coverage = records.coverage();
      const result = profileSearchResult({
        profileId: records.profile().id,
        query: input.query,
        matches,
        allReferences: records.libraryReferences(),
        sources: librarySources(records),
        coverage,
        limit: input.limit,
      });
      return {
        ...result,
        status,
        searchMode: status === 'ok' ? 'semantic' : 'saved_text',
        autonomy: records.referenceAutonomy(),
        coverage: { ...result.coverage, pendingIndex: coverage.pendingIndex },
      };
    };
    if (!isMemoryPlatformSupported()) return respond('unsupported_platform');
    if (!records.coverage().indexed) return respond('not_indexed');
    const started = await startEngineForAgent(context.memory, {
      onStarted: () => {
        engine.isStarted = true;
      },
    });
    if (started !== 'ok') return respond(started);
    try {
      const matches = await context.index.searchLibrary({
        runtime: input.runtime,
        query: input.query,
        sourceFilterId: input.sourceId,
        signal: AbortSignal.any([
          context.abort.signal,
          AbortSignal.timeout(AGENT_QUERY_TIMEOUT_MS),
        ]),
        binding: AGENT_SEARCH_BINDING,
      });
      return respond('ok', matches);
    } catch (error) {
      log.warn('Semantic reference search unavailable; using saved text', {
        error: errorMessage(error, 'Semantic reference search failed'),
      });
      return respond(agentSearchFailureStatus(error) ?? 'engine_failed');
    }
  }

  async referenceContexts(input: DesignReferenceRequest) {
    return this.withReferenceRecords((records) =>
      this.readReferenceContexts(records, input),
    );
  }

  private async readReferenceContexts(
    records: ProfileRecords,
    input: DesignReferenceRequest,
  ) {
    if (records.profile().id !== input.profileId) return null;
    const select = () => resolveReferenceKeys(records, input.keys);
    const selected = select();
    if (!selected) return null;
    const summarize = ({ key, reference }: (typeof selected)[number]) => ({
      key,
      title: reference.title,
      imageCount: reference.media.length,
      hasAnalysis: hasCompletedAnalysis(reference.observation),
    });
    if (!input.isDetailed) return { references: selected.map(summarize) };
    const media = new ProfileMedia(records.directory);
    const paths = new Map<string, string | null>();
    for (const { reference } of selected) {
      for (const image of reference.media) {
        if (paths.has(image.hash)) continue;
        try {
          paths.set(image.hash, await media.resolve(image));
        } catch (error) {
          if (
            typeof error !== 'object' ||
            error === null ||
            !('code' in error) ||
            error.code !== 'ENOENT'
          )
            throw error;
          paths.set(image.hash, null);
        }
      }
    }
    const current = select();
    if (!current) return null;
    const sources = records.sources();
    return {
      references: current.map((entry): DesignReferenceContext => {
        const { reference } = entry;
        const contextImages = reference.media.flatMap((image) => {
          const location = paths.get(image.hash);
          return location ? [location] : [];
        });
        return {
          ...summarize(entry),
          text: reference.text,
          ...(reference.note ? { note: reference.note } : {}),
          analysis: reference.observation
            ? {
                description: reference.observation.description,
                evidence: reference.observation.evidence,
              }
            : null,
          sources: sources
            .filter((source) => reference.sourceIds.includes(source.id))
            .map(({ id, title, provider, isIncluded, syncMode }) => ({
              id,
              title,
              provider,
              isIncluded,
              syncMode,
            })),
          contextImages,
          missingMediaCount: reference.media.length - contextImages.length,
        };
      }),
    };
  }

  async referenceMedia({
    profileId,
    referenceId,
    hash,
  }: {
    profileId: string;
    referenceId: string;
    hash: string;
  }) {
    return this.withReferenceRecords(async (records) => {
      if (records.profile().id !== profileId) return null;
      const reference = records.libraryReferences([referenceId])[0];
      const media = reference?.media.find((item) => item.hash === hash);
      if (!media) return null;
      try {
        const bytes = await new ProfileMedia(records.directory).read(media);
        return { bytes, mimeType: media.mimeType };
      } catch (error) {
        if (
          typeof error === 'object' &&
          error !== null &&
          'code' in error &&
          error.code === 'ENOENT'
        )
          return null;
        throw error;
      }
    });
  }

  async inspect(requestId: string): Promise<RecordedContext | null> {
    const accountId = this.options.accountId();
    if (!accountId)
      throw new Error('Sign in to Rivet to inspect profile context');
    const result = await readProfileContext({
      directory: ProfileRecords.directoryFor({
        root: this.options.root,
        accountId,
      }),
      requestId,
    });
    if (accountId !== this.options.accountId())
      throw new Error('Profile account changed during inspection');
    return result;
  }

  async recordContext(input: {
    profileId: string;
    context: RecordedContext;
  }): Promise<RecordedContext> {
    const context = ProfileContextSchema.parse(input.context);
    const accountId = this.options.accountId();
    if (!accountId)
      throw new Error('Sign in to Rivet to record profile context');
    const records = await ProfileRecords.open({
      root: this.options.root,
      accountId,
    });
    try {
      if (
        input.profileId !== records.profile().id ||
        accountId !== this.options.accountId()
      )
        throw new ProfileContextConflict(
          'Profile account changed before context could be recorded',
        );
      return await writeProfileContext({
        directory: records.directory,
        context,
      });
    } finally {
      records.close();
    }
  }

  async prepare(input: PreparationInput, accountId = this.options.accountId()) {
    const request = ProfilePreparationRequestSchema.parse(input);
    const uploads = request.uploads ?? [];
    let suppliedBytes = 0;
    const suppliedMediaHashes = uploads.map((image) => {
      const bytes = Buffer.from(image.slice(image.indexOf(',') + 1), 'base64');
      suppliedBytes += bytes.length;
      if (suppliedBytes > PROFILE_UPLOAD_BYTES)
        throw new Error('Supplied images exceed the profile upload budget');
      return createHash('sha256').update(bytes).digest('hex');
    });
    const validated = ProfilePreparationSchema.parse({
      ...request,
      suppliedInputHashes: uploads.length
        ? uploads.map((image) =>
            createHash('sha256').update(image).digest('hex'),
          )
        : undefined,
      excludedMediaHashes: [
        ...new Set([...request.excludedMediaHashes, ...suppliedMediaHashes]),
      ],
    });
    const context = await this.context();
    if (
      !accountId ||
      context.accountId !== accountId ||
      accountId !== this.options.accountId()
    )
      throw new Error('Profile account changed before preparation');
    const autonomySetting = context.records.referenceAutonomy();
    const pickTrigger = validated.referencePicks
      ? (validated.pickTrigger ?? 'autonomous')
      : undefined;
    if (
      validated.referencePicks &&
      validated.mode === 'auto' &&
      pickTrigger === 'autonomous' &&
      autonomySetting === 'off'
    ) {
      const error = new ProfileContextConflict(AUTONOMY_OFF_MESSAGE);
      this.options.telemetry?.trackProfileOperation({
        stage: 'preparation',
        operation: 'preparation',
        outcome: 'failed',
        durationMs: 0,
        autonomySetting,
        pickTrigger,
        error,
      });
      throw error;
    }
    const signal = context.abort.signal;
    const packet = await context.preparation.prepare(validated, {
      signal,
      ...(uploads.length
        ? {
            saveUploads: (preparationSignal) =>
              this.saveSuppliedImages({
                context,
                uploads,
                runtime: validated.runtime,
                signal: preparationSignal,
              }),
          }
        : {}),
    });
    signal.throwIfAborted();
    if (accountId !== this.options.accountId())
      throw new Error('Profile account changed during preparation');
    const result =
      !context.records.profile().isEnabled && packet.suppliedReferences?.length
        ? {
            ...packet,
            status: 'off' as const,
            selected: [],
            images: [],
            contextText: '',
            suppliedReferences: undefined,
            failedUploadCount: undefined,
          }
        : packet;
    const selectedProviders = result.selected.flatMap(
      (item) => context.records.reference(item.id)?.provider ?? [],
    );
    this.options.telemetry?.trackProfileOperation({
      stage: 'preparation',
      operation: 'preparation',
      outcome: 'completed',
      durationMs: result.durationMs,
      referenceCount: result.selected.length,
      candidateCount: result.candidateIds.length,
      status: result.status,
      autonomySetting,
      ...(pickTrigger ? { pickTrigger } : {}),
      ...(result.selected.length
        ? {
            selectedBy: result.selected.some(
              (item) => item.selectedBy === 'host',
            )
              ? ('host' as const)
              : ('rivet' as const),
          }
        : {}),
      ...(selectedProviders.length
        ? { providerMix: [...new Set(selectedProviders)].sort() }
        : {}),
      ...(result.status === 'off'
        ? {
            offReason: preparationOffReason({
              mode: validated.mode,
              isEnabled: context.records.profile().isEnabled,
            }),
          }
        : {}),
    });
    return { ...result, profileId: context.records.profile().id, accountId };
  }

  private async saveSuppliedImages({
    context,
    uploads,
    runtime,
    signal,
  }: {
    context: ProfileContext;
    uploads: string[];
    runtime: ProfileRuntime;
    signal: AbortSignal;
  }) {
    const started = Date.now();
    const suppliedReferences: VariantReference[] = [];
    let failedUploadCount = 0;
    const assertAccount = () => {
      signal.throwIfAborted();
      if (context.accountId !== this.options.accountId())
        throw new Error('Profile account changed while saving supplied images');
      if (!context.records.profile().isEnabled)
        throw new Error('Profile disabled while saving supplied images');
    };
    for (const upload of uploads) {
      assertAccount();
      try {
        const match = /^data:([^;,]+);base64,([A-Za-z0-9+/=\s]+)$/.exec(upload);
        if (!match) throw new Error('Supplied image must be a base64 data URL');
        const media = await context.media.put(Buffer.from(match[2], 'base64'));
        assertAccount();
        if (media.mimeType !== match[1].trim().toLowerCase())
          throw new Error('Supplied image MIME type does not match its bytes');
        let reference = context.records
          .references()
          .find(
            (candidate) =>
              candidate.provider === 'image' &&
              candidate.remoteId === media.hash,
          );
        if (!reference) {
          const saved = context.records.saveLocalImport({
            source: {
              provider: 'image',
              remoteId: media.hash,
              title: 'Uploaded reference',
            },
            reference: {
              provider: 'image',
              remoteId: media.hash,
              title: 'Uploaded reference',
              text: '',
              media: [media],
            },
            runtime,
          });
          reference = context.records.references(saved.source.id)[0];
          this.enqueueImport(context, saved.job.id, 'attachment');
        }
        if (!reference) throw new Error('Saved image reference is unavailable');
        if (!suppliedReferences.some((item) => item.id === reference.id))
          suppliedReferences.push({
            id: reference.id,
            title: reference.title,
            image: { hash: media.hash, mimeType: media.mimeType },
          });
      } catch {
        assertAccount();
        failedUploadCount += 1;
      }
    }
    this.options.telemetry?.trackProfileOperation({
      stage: 'action',
      operation: 'image_import',
      outcome: failedUploadCount ? 'failed' : 'completed',
      durationMs: Date.now() - started,
      referenceCount: suppliedReferences.length,
    });
    return {
      suppliedReferences,
      ...(failedUploadCount ? { failedUploadCount } : {}),
    };
  }

  async close(): Promise<void> {
    this.isClosed = true;
    this.closing.abort();
    await this.sourceSync.close();
    await this.opening?.catch(() => undefined);
    const context = this.current;
    this.current = undefined;
    if (context) {
      context.schedule.stop();
      context.abort.abort();
      await this.options.variants?.close();
      await context.memory.close();
      await context.work;
      await Promise.allSettled(context.directWrites);
      context.records.close();
    }
  }

  private async context({
    shouldResume = true,
  }: { shouldResume?: boolean } = {}): Promise<ProfileContext> {
    const context = await this.openContext();
    if (
      shouldResume &&
      !context.isResumed &&
      context.records.profile().isEnabled
    )
      this.resume(context);
    return context;
  }

  private async openContext(): Promise<ProfileContext> {
    if (this.isClosed) throw new Error('Design profiles are closed');
    const accountId = this.options.accountId();
    if (!accountId) throw new Error('Sign in to Rivet to use design profiles');
    if (this.opening) {
      await this.opening;
      return this.openContext();
    }
    if (this.current?.accountId === accountId) return this.current;
    this.opening = (async () => {
      const prior = this.current;
      this.current = undefined;
      if (prior) {
        prior.schedule.stop();
        prior.abort.abort();
        await prior.memory.close();
        await prior.work;
        await Promise.allSettled(prior.directWrites);
        prior.records.close();
      }
      const records = await ProfileRecords.open({
        root: this.options.root,
        accountId,
      });
      const agent = new ProfileAgent(
        path.join(records.directory, 'tasks'),
        this.options.runnerPaths,
      );
      const media = new ProfileMedia(records.directory);
      const memory = new MemoryRuntime({
        directory: records.directory,
        componentRoot:
          this.options.componentRoot ??
          path.join(os.homedir(), '.rivet', 'components'),
        agent,
      });
      const index = new ProfileIndex(records, memory);
      const context: ProfileContext = {
        accountId,
        records,
        agent,
        media,
        memory,
        index,
        preparation: new ProfilePreparation(records, index, agent, media),
        imports: new ProfileImports(
          records,
          media,
          () => this.options.accountId() === accountId,
        ),
        analysis: new ProfileAnalysis({
          records,
          media,
          agent,
          isCurrentAccount: () => this.options.accountId() === accountId,
          telemetry: this.options.telemetry,
        }),
        schedule: new ProfileImportSchedule({
          records,
          isActive: () =>
            this.current === context &&
            !context.abort.signal.aborted &&
            this.options.accountId() === accountId,
          onReady: (id) => this.enqueueImport(context, id, 'cooldown_retry'),
        }),
        abort: new AbortController(),
        work: Promise.resolve(),
        directWrites: new Set(),
        isResumed: false,
        issue: null,
      };
      this.current = context;
      return context;
    })();
    try {
      const context = await this.opening;
      if (this.isClosed) throw new Error('Design profiles are closed');
      return context;
    } finally {
      this.opening = undefined;
    }
  }

  private resume(
    context: ProfileContext,
    claimedJobIds: readonly string[] = [],
  ): void {
    context.isResumed = true;
    const { signal } = context.abort;
    context.memory.start().then(
      () => {
        if (!signal.aborted) context.issue = null;
      },
      (error: unknown) => {
        if (!signal.aborted)
          context.issue = errorMessage(error, 'Profile operation failed');
      },
    );
    for (const job of context.records
      .jobs()
      .filter(
        (job) => job.state === 'pending' && !claimedJobIds.includes(job.id),
      ))
      this.enqueueImport(context, job.id, 'resume');
    this.enqueue(context, () => this.runRebuild(context));
  }

  private enqueue(
    context: ProfileContext,
    operation: () => Promise<void>,
  ): void {
    context.work = context.work
      .then(async () => {
        context.abort.signal.throwIfAborted();
        if (context.accountId !== this.options.accountId())
          throw new Error(
            'Profile work paused because the active account changed',
          );
        await operation();
      })
      .catch((error: unknown) => {
        context.issue = errorMessage(error, 'Profile operation failed');
      });
  }

  private enqueueImport(
    context: ProfileContext,
    id: string,
    kind: ProfileImportKind,
  ): void {
    const queuedAt = Date.now();
    const job = context.records.jobs().find((item) => item.id === id);
    this.options.telemetry?.trackProfileOperation({
      stage: 'import',
      operation: 'import',
      outcome: 'queued',
      durationMs: 0,
      jobId: id,
      importKind: kind,
      provider: context.records
        .sources()
        .find((source) => source.id === job?.sourceId)?.provider,
    });
    this.enqueue(context, () => this.runImport(context, id, kind, queuedAt));
  }

  private async flush(
    context: ProfileContext,
    runtime: ProfileRuntime,
  ): Promise<void> {
    while (context.records.pendingIndex(1).length)
      await context.index.flush(runtime, context.abort.signal);
  }

  private indexSavedEvidence(
    context: ProfileContext,
    runtime: ProfileRuntime,
  ): void {
    if (context.savedEvidenceIndexing || !isMemoryPlatformSupported()) return;
    const { signal } = context.abort;
    const indexing = context.memory
      .start()
      .then(() => this.flush(context, runtime))
      .catch((error: unknown) => {
        if (!signal.aborted)
          log.warn('Saved reference evidence could not be indexed yet', {
            error: errorMessage(error, 'Profile index catch-up failed'),
          });
      })
      .finally(() => {
        context.savedEvidenceIndexing = undefined;
        context.directWrites.delete(indexing);
      });
    context.savedEvidenceIndexing = indexing;
    context.directWrites.add(indexing);
  }

  private async enumeratePlanned(
    context: ProfileContext,
    jobId: string,
    planned: NonNullable<ReturnType<ProfileRecords['plans']['sourcePlan']>>,
  ): Promise<void> {
    const isPending = () => {
      const job = context.records.jobs().find((item) => item.id === jobId);
      return job?.state === 'pending' && !job.isEnumerated;
    };
    if (!isPending()) return;
    const discovery = context.records.plans.discovery(planned.discoveryId);
    const collection = discovery.collections.find(
      (item) => item.id === planned.collectionId,
    );
    if (!collection)
      throw new Error('The approved collection is missing from its discovery');
    const provider = referenceProvider(discovery.profile);
    const references = await this.planning(context.records, context.accountId)
      .readApprovedCollections({
        profile: discovery.profile,
        collection,
        collectionIds: planned.collectionIds,
        isJobActive: isPending,
        signal: context.abort.signal,
      })
      .catch((error: unknown) => {
        if (error instanceof ReferenceConnectionError)
          throw new Error(reconnectRequiredMessage(provider));
        throw error;
      });
    if (!references || !isPending()) return;
    context.records.saveImportPage({
      jobId,
      references,
      cursor: null,
      isComplete: true,
      total: references.length,
      shouldPruneUnseen: false,
    });
  }

  private async runImport(
    context: ProfileContext,
    id: string,
    kind: ProfileImportKind,
    queuedAt: number,
  ): Promise<void> {
    if (!context.schedule.isReady(id)) return;
    const job = context.records.jobs().find((item) => item.id === id);
    if (!job || job.state !== 'pending') return;
    const jobSource = context.records.source(job.sourceId);
    if (
      isRemoteProfileProvider(jobSource.provider) &&
      !isSourceSyncAllowed({
        syncMode: jobSource.syncMode,
        trigger: kind === 'auto_refresh' ? 'automatic' : 'explicit',
      })
    )
      return;
    const started = Date.now();
    const importContext = {
      provider: context.records
        .sources()
        .find((source) => source.id === job.sourceId)?.provider,
      importKind: kind,
      jobId: id,
    };
    this.options.telemetry?.trackProfileOperation({
      stage: 'import',
      operation: 'import',
      outcome: 'started',
      durationMs: started - queuedAt,
      ...importContext,
    });
    const syncTimes = context.records
      .jobs()
      .filter(
        (item) => item.sourceId === job.sourceId && item.state === 'complete',
      )
      .map((item) => Date.parse(item.updatedAt));
    const lastSyncedAt = syncTimes.length ? Math.max(...syncTimes) : undefined;
    let step: ProfileImportStep = 'analysis';
    try {
      const source = context.records.source(job.sourceId);
      const isSync = isRemoteProfileProvider(source.provider);
      const indexSavedEvidence = () =>
        this.indexSavedEvidence(context, job.runtime);
      if (isSync) {
        step = 'enumerate';
        const planned = context.records.plans.sourcePlan(source.id);
        if (planned) await this.enumeratePlanned(context, id, planned);
        else
          await context.imports.enumerate(
            id,
            context.abort.signal,
            indexSavedEvidence,
          );
        indexSavedEvidence();
        step = 'download';
        await context.imports.download(
          id,
          context.abort.signal,
          indexSavedEvidence,
        );
      }
      indexSavedEvidence();
      step = 'analysis';
      await context.analysis.run({ jobId: id, signal: context.abort.signal });
      if (
        context.records.jobs().find((item) => item.id === id)?.state !==
        'pending'
      )
        return;
      step = 'memory_start';
      await context.memory.start();
      step = 'index';
      context.records.queueIndex(job.runtime);
      await this.runRebuild(context);
      if (
        context.records.jobs().find((item) => item.id === id)?.state !==
        'pending'
      )
        return;
      context.records.updateJob({ id, state: 'complete' });
      const completed = context.records.jobs().find((item) => item.id === id);
      this.options.telemetry?.trackProfileOperation({
        stage: 'import',
        operation: 'import',
        outcome: 'completed',
        durationMs: Date.now() - started,
        referenceCount: context.records.references(job.sourceId).length,
        ...importContext,
        ...(isSync && completed
          ? {
              addedCount: completed.addedCount,
              removedCount: completed.removedCount,
              ...(lastSyncedAt === undefined
                ? {}
                : { staleHours: (started - lastSyncedAt) / MS_PER_HOUR }),
            }
          : {}),
      });
    } catch (error) {
      if (
        error instanceof ProviderRateLimit &&
        !context.abort.signal.aborted &&
        context.accountId === this.options.accountId() &&
        context.records.profile().isEnabled
      ) {
        context.records.deferImport({ id, retryAfterMs: error.retryAfterMs });
        context.schedule.isReady(id);
        this.options.telemetry?.trackProfileOperation({
          stage: 'import',
          operation: 'import',
          outcome: 'deferred',
          durationMs: Date.now() - started,
          ...importContext,
        });
        return;
      }
      const failedStep = error instanceof UnfinishedImport ? error.step : step;
      this.options.telemetry?.trackProfileOperation({
        stage: 'import',
        operation: 'import',
        outcome: 'failed',
        durationMs: Date.now() - started,
        ...importContext,
        failedStep,
        error,
      });
      if (
        !context.abort.signal.aborted &&
        context.records.jobs().find((item) => item.id === id)?.state ===
          'pending'
      )
        context.records.updateJob({
          id,
          state: 'failed',
          error: errorMessage(error, 'Profile import failed'),
        });
      throw error;
    }
  }
}
